      "B": "Dans le triangle fémoral, la veine fémorale est latérale à l'artère fémorale.",
      "C": "Dans le canal des adducteurs, le nerf saphène est antérieur à l'artère.",
      "D": "L'hiatus du grand adducteur est limité par les faisceaux moyen et inférieur du muscle long adducteur.",
